import { useState } from 'react';

export function MobileMenu() {
  const [open, setOpen] = useState(false);
  const items = {{items}};
  return (
    <div className="md:hidden">
      <button onClick={() => setOpen(!open)} className="p-2">
        <span className="block h-0.5 w-6 bg-black mb-1" />
        <span className="block h-0.5 w-6 bg-black mb-1" />
        <span className="block h-0.5 w-6 bg-black" />
      </button>
      {open && (
        <div className="fixed inset-0 z-50 bg-white p-6">
          <button onClick={() => setOpen(false)} className="absolute right-4 top-4 text-2xl">✕</button>
          <nav className="mt-12 flex flex-col gap-4">
            {items.map((it) => (
              <a key={it.href} href={it.href} className="text-lg">{it.label}</a>
            ))}
          </nav>
        </div>
      )}
    </div>
  );
}
